        function getDefaultBusinessWorkspace() {
            return {
                projects: [],
                clients: [],
                invoices: [],
                finance: [],
                opportunities: [],
                meetings: [],
                proposals: [],
                tasks: [],
                documents: [],
                goals: [],
                notes: [],
                activity: [],
                quickCapture: '',
                quickCaptureUpdatedAt: '',
                currency: 'USD'
            };
        }

        function getDefaultBusinessUiState() {
            return {
                search: '',
                compact: false,
                detail: { entityType: '', entityId: '', tab: 'summary' },
                modal: null,
                sections: JSON.parse(JSON.stringify(BUSINESS_SECTION_UI_DEFAULTS)),
                focusQuickNote: false
            };
        }

        function getDefaultUiState() {
            return {
                defaultPageId: null,
                lastActiveView: 'today',
                lastOpenedPageId: null,
                pageScrollPositions: {}
            };
        }

        function normalizeBusinessWorkspace(data) {
            const defaults = getDefaultBusinessWorkspace();
            const source = data && typeof data === 'object' ? data : {};
            const normalized = { ...defaults, ...source };
            const clients = Array.isArray(source.clients) ? source.clients.map(row => createBusinessClientRow(row)) : defaults.clients;
            const clientLookup = new Map();
            clients.forEach(client => {
                if (client.name) clientLookup.set(client.name.toLowerCase(), client.id);
                if (client.company) clientLookup.set(client.company.toLowerCase(), client.id);
            });
            normalized.clients = clients;
            normalized.projects = Array.isArray(source.projects) ? source.projects.map(row => createBusinessProjectRow(row)) : defaults.projects;
            normalized.invoices = Array.isArray(source.invoices)
                ? source.invoices.map(row => createBusinessInvoiceRow({
                    ...row,
                    clientId: row && row.clientId ? row.clientId : (clientLookup.get(String(row && row.client || '').trim().toLowerCase()) || '')
                }))
                : defaults.invoices;
            normalized.finance = Array.isArray(source.finance) ? source.finance.map(row => createBusinessFinanceRow(row)) : defaults.finance;
            normalized.opportunities = Array.isArray(source.opportunities) ? source.opportunities.map(row => createBusinessOpportunityRow(row)) : defaults.opportunities;
            normalized.meetings = Array.isArray(source.meetings) ? source.meetings.map(row => createBusinessMeetingRow(row)) : defaults.meetings;
            normalized.proposals = Array.isArray(source.proposals) ? source.proposals.map(row => createBusinessProposalRow(row)) : defaults.proposals;
            normalized.tasks = Array.isArray(source.tasks) ? source.tasks.map(row => createBusinessTaskRow(row)) : defaults.tasks;
            normalized.documents = Array.isArray(source.documents) ? source.documents.map(row => createBusinessDocumentRow(row)) : defaults.documents;
            normalized.goals = Array.isArray(source.goals) ? source.goals.map(row => createBusinessGoalRow(row)) : defaults.goals;
            normalized.notes = Array.isArray(source.notes) ? source.notes.map(row => createBusinessNoteRow(row)) : [];
            normalized.activity = Array.isArray(source.activity) ? source.activity.map(row => createBusinessActivityRow(row)).slice(0, 160) : [];
            normalized.quickCapture = String(source.quickCapture || (typeof source.notes === 'string' ? source.notes : '') || '').trimStart();
            normalized.quickCaptureUpdatedAt = normalizeBusinessTimestamp(source.quickCaptureUpdatedAt, '');
            normalized.currency = String(source.currency || 'USD').trim().toUpperCase() || 'USD';
            return normalized;
        }

        // ----------------------------------------------------------------------
        // Review (spaced repetition) workspace defaults & normalization.
        // Stored as a top-level key (`reviewWorkspace`) so it travels through
        // the same save/export/import path as every other workspace area and
        // survives JSON, .atelier, hydration defaults, and round-trip tests.
        // ----------------------------------------------------------------------
        function getDefaultReviewWorkspace() {
            return {
                decks: [],
                items: [],
                sessions: [],
                settings: {
                    dailyLimit: 30,
                    newItemsPerDay: 10,
                    interleaveDecks: true,
                    showAnswerMode: 'manual',
                    defaultStudyMode: 'flashcards',
                    learnRequiresExact: false,
                    testQuestionCount: 20,
                    testQuestionTypes: ['written', 'mc', 'tf'],
                    matchPairCount: 6,
                    shuffleCards: true,
                    frontSide: 'prompt'
                }
            };
        }

        function normalizeReviewSettings(raw) {
            const defaults = getDefaultReviewWorkspace().settings;
            const source = raw && typeof raw === 'object' ? raw : {};
            const dailyLimit = Math.max(1, Math.min(500, parseInt(source.dailyLimit, 10) || defaults.dailyLimit));
            const newItemsPerDay = Math.max(0, Math.min(200, parseInt(source.newItemsPerDay, 10) || defaults.newItemsPerDay));
            const showAnswerMode = ['manual', 'auto', 'tap'].includes(source.showAnswerMode) ? source.showAnswerMode : defaults.showAnswerMode;
            const allowedModes = ['flashcards', 'learn', 'write', 'test', 'match'];
            const defaultStudyMode = allowedModes.includes(source.defaultStudyMode) ? source.defaultStudyMode : (defaults.defaultStudyMode || 'flashcards');
            const allowedTestTypes = new Set(['written', 'mc', 'tf', 'match']);
            const rawTestTypes = Array.isArray(source.testQuestionTypes) ? source.testQuestionTypes.filter(t => allowedTestTypes.has(t)) : [];
            const testQuestionTypes = rawTestTypes.length ? rawTestTypes : (defaults.testQuestionTypes || ['written', 'mc', 'tf']);
            const frontSide = source.frontSide === 'answer' ? 'answer' : 'prompt';
            return {
                dailyLimit,
                newItemsPerDay,
                interleaveDecks: source.interleaveDecks !== false,
                showAnswerMode,
                defaultStudyMode,
                learnRequiresExact: source.learnRequiresExact === true,
                testQuestionCount: Math.max(5, Math.min(200, parseInt(source.testQuestionCount, 10) || (defaults.testQuestionCount || 20))),
                testQuestionTypes,
                matchPairCount: Math.max(4, Math.min(20, parseInt(source.matchPairCount, 10) || (defaults.matchPairCount || 6))),
                shuffleCards: source.shuffleCards !== false,
                frontSide
            };
        }

        function normalizeReviewDeck(raw) {
            const source = raw && typeof raw === 'object' ? raw : {};
            const id = String(source.id || '').trim();
            const name = String(source.name || '').trim() || 'Untitled deck';
            const allowedModes = ['flashcards', 'learn', 'write', 'test', 'match'];
            const studyMode = allowedModes.includes(source.studyMode) ? source.studyMode : 'flashcards';
            const bestMatchTime = (source.bestMatchTimeMs && Number.isFinite(parseInt(source.bestMatchTimeMs, 10)))
                ? Math.max(0, parseInt(source.bestMatchTimeMs, 10))
                : null;
            return {
                id: id || `deck_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
                name,
                description: String(source.description || ''),
                subject: String(source.subject || ''),
                sourceType: String(source.sourceType || ''),
                sourceId: source.sourceId ? String(source.sourceId) : null,
                color: String(source.color || ''),
                archived: source.archived === true,
                studyMode,
                lastStudiedAt: source.lastStudiedAt || null,
                bestMatchTimeMs: bestMatchTime,
                createdAt: source.createdAt || new Date().toISOString(),
                updatedAt: source.updatedAt || new Date().toISOString()
            };
        }

        function normalizeReviewItem(raw) {
            const source = raw && typeof raw === 'object' ? raw : {};
            const id = String(source.id || '').trim();
            const tags = Array.isArray(source.tags) ? source.tags.map(t => String(t)).filter(Boolean) : [];
            const status = ['new', 'learning', 'reviewing', 'lapsed', 'suspended'].includes(source.status) ? source.status : 'new';
            const intervalDays = Math.max(0, parseFloat(source.intervalDays) || 0);
            const ease = Math.max(1.3, parseFloat(source.ease) || 2.5);
            const repetitions = Math.max(0, parseInt(source.repetitions, 10) || 0);
            const lapses = Math.max(0, parseInt(source.lapses, 10) || 0);
            const mastery = ['new', 'learning', 'familiar', 'mastered'].includes(source.mastery)
                ? source.mastery
                : (status === 'reviewing' ? 'familiar' : 'new');
            return {
                id: id || `item_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
                deckId: String(source.deckId || ''),
                prompt: String(source.prompt || ''),
                answer: String(source.answer || ''),
                hint: String(source.hint || ''),
                imageUrl: String(source.imageUrl || ''),
                starred: source.starred === true,
                mastery,
                correctCount: Math.max(0, parseInt(source.correctCount, 10) || 0),
                incorrectCount: Math.max(0, parseInt(source.incorrectCount, 10) || 0),
                studyTimeSeconds: Math.max(0, parseInt(source.studyTimeSeconds, 10) || 0),
                tags,
                sourceType: String(source.sourceType || ''),
                sourceId: source.sourceId ? String(source.sourceId) : null,
                sourceNoteId: source.sourceNoteId ? String(source.sourceNoteId) : null,
                sourceApClassId: source.sourceApClassId ? String(source.sourceApClassId) : null,
                sourceAssignmentId: source.sourceAssignmentId ? String(source.sourceAssignmentId) : null,
                sourceProjectId: source.sourceProjectId ? String(source.sourceProjectId) : null,
                generationReason: String(source.generationReason || ''),
                sourceCitation: source.sourceCitation && typeof source.sourceCitation === 'object'
                    ? cloneSerializable(source.sourceCitation, {})
                    : null,
                difficulty: String(source.difficulty || 'medium'),
                status,
                nextReviewAt: source.nextReviewAt || new Date().toISOString(),
                lastReviewedAt: source.lastReviewedAt || null,
                intervalDays,
                ease,
                repetitions,
                lapses,
                createdAt: source.createdAt || new Date().toISOString(),
                updatedAt: source.updatedAt || new Date().toISOString()
            };
        }

        function normalizeReviewSession(raw) {
            const source = raw && typeof raw === 'object' ? raw : {};
            const allowedGrades = ['again', 'hard', 'good', 'easy', 'correct', 'incorrect'];
            const itemResults = Array.isArray(source.itemResults) ? source.itemResults.filter(r => r && typeof r === 'object').map(r => ({
                itemId: String(r.itemId || ''),
                grade: allowedGrades.includes(r.grade) ? r.grade : 'good',
                reviewedAt: r.reviewedAt || new Date().toISOString(),
                intervalDays: parseFloat(r.intervalDays) || 0
            })) : [];
            const allowedModes = ['flashcards', 'learn', 'write', 'test', 'match'];
            const mode = allowedModes.includes(source.mode) ? source.mode : 'flashcards';
            return {
                id: String(source.id || `session_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`),
                startedAt: source.startedAt || new Date().toISOString(),
                endedAt: source.endedAt || null,
                deckIds: Array.isArray(source.deckIds) ? source.deckIds.map(String) : [],
                mode,
                itemResults,
                totalReviewed: parseInt(source.totalReviewed, 10) || itemResults.length,
                againCount: parseInt(source.againCount, 10) || 0,
                hardCount: parseInt(source.hardCount, 10) || 0,
                goodCount: parseInt(source.goodCount, 10) || 0,
                easyCount: parseInt(source.easyCount, 10) || 0,
                correctCount: parseInt(source.correctCount, 10) || 0,
                incorrectCount: parseInt(source.incorrectCount, 10) || 0,
                score: parseFloat(source.score) || 0,
                totalQuestions: parseInt(source.totalQuestions, 10) || itemResults.length,
                timeMs: Math.max(0, parseInt(source.timeMs, 10) || 0),
                linkedFocusSessionId: source.linkedFocusSessionId ? String(source.linkedFocusSessionId) : null,
                createdAt: source.createdAt || new Date().toISOString()
            };
        }

        function normalizeReviewWorkspace(raw) {
            const defaults = getDefaultReviewWorkspace();
            if (!raw || typeof raw !== 'object') return defaults;
            const decks = Array.isArray(raw.decks) ? raw.decks.map(normalizeReviewDeck) : [];
            const deckIds = new Set(decks.map(d => d.id));
            const items = Array.isArray(raw.items) ? raw.items.map(normalizeReviewItem).filter(item => item.deckId && deckIds.has(item.deckId)) : [];
            const sessions = Array.isArray(raw.sessions) ? raw.sessions.map(normalizeReviewSession).slice(0, 200) : [];
            return {
                decks,
                items,
                sessions,
                settings: normalizeReviewSettings(raw.settings)
            };
        }

        // ----------------------------------------------------------------------
        // Focus templates: reusable focus rituals that link to a project, AP
        // class, review deck, or note. Stored as a top-level array.
        // ----------------------------------------------------------------------
        function getDefaultFocusTemplates() {
            const now = new Date().toISOString();
            return [
                { id: 'tpl_deep_work', name: 'Deep Work', durationMinutes: 50, mode: 'timer', linkedView: '', linkedProjectId: null, linkedApClassId: null, linkedReviewDeckId: null, defaultGoal: 'Single hard task, no context-switching.', ambientMode: '', createdAt: now, updatedAt: now },
                { id: 'tpl_ap_review', name: 'AP Review', durationMinutes: 25, mode: 'timer', linkedView: 'apstudy', linkedProjectId: null, linkedApClassId: null, linkedReviewDeckId: null, defaultGoal: 'Active recall on an AP unit.', ambientMode: '', createdAt: now, updatedAt: now },
                { id: 'tpl_homework_sprint', name: 'Homework Sprint', durationMinutes: 30, mode: 'timer', linkedView: 'homework', linkedProjectId: null, linkedApClassId: null, linkedReviewDeckId: null, defaultGoal: 'Knock out one assignment.', ambientMode: '', createdAt: now, updatedAt: now },
                { id: 'tpl_reading_block', name: 'Reading Block', durationMinutes: 40, mode: 'timer', linkedView: 'life', linkedProjectId: null, linkedApClassId: null, linkedReviewDeckId: null, defaultGoal: 'Steady reading, take light notes.', ambientMode: '', createdAt: now, updatedAt: now },
                { id: 'tpl_project_build', name: 'Project Build', durationMinutes: 60, mode: 'timer', linkedView: 'notes', linkedProjectId: null, linkedApClassId: null, linkedReviewDeckId: null, defaultGoal: 'Ship a chunk of a project.', ambientMode: '', createdAt: now, updatedAt: now },
                { id: 'tpl_review_focus', name: 'Review Focus', durationMinutes: 20, mode: 'timer', linkedView: 'review', linkedProjectId: null, linkedApClassId: null, linkedReviewDeckId: null, defaultGoal: 'Clear the review queue.', ambientMode: '', createdAt: now, updatedAt: now }
            ];
        }

        function normalizeFocusTemplate(raw) {
            const source = raw && typeof raw === 'object' ? raw : {};
            const duration = Math.max(1, Math.min(240, parseInt(source.durationMinutes, 10) || 25));
            return {
                id: String(source.id || `tpl_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`),
                name: String(source.name || '').trim() || 'Focus block',
                durationMinutes: duration,
                mode: ['timer', 'stopwatch'].includes(source.mode) ? source.mode : 'timer',
                linkedView: source.linkedView ? String(source.linkedView) : '',
                linkedProjectId: source.linkedProjectId ? String(source.linkedProjectId) : null,
                linkedApClassId: source.linkedApClassId ? String(source.linkedApClassId) : null,
                linkedReviewDeckId: source.linkedReviewDeckId ? String(source.linkedReviewDeckId) : null,
                linkedNoteId: source.linkedNoteId ? String(source.linkedNoteId) : null,
                defaultGoal: String(source.defaultGoal || ''),
                ambientMode: String(source.ambientMode || ''),
                createdAt: source.createdAt || new Date().toISOString(),
                updatedAt: source.updatedAt || new Date().toISOString()
            };
        }

        function normalizeFocusTemplates(raw) {
            if (!Array.isArray(raw)) return getDefaultFocusTemplates();
            const list = raw.map(normalizeFocusTemplate);
            return list.length ? list : getDefaultFocusTemplates();
        }

        // ----------------------------------------------------------------------
        // Split-view pane contexts: deeper-than-tab memory of which note,
        // review deck, AP class, etc. is selected in each pane. Stored as a
        // top-level object so it survives reloads and exports.
        // ----------------------------------------------------------------------
        function getDefaultSplitPaneContexts() {
            return {
                leftView: 'notes',
                rightView: 'review',
                layout: 'half',
                leftContext: getDefaultPaneContext(),
                rightContext: getDefaultPaneContext(),
                lastUpdatedAt: null
            };
        }

        function getDefaultPaneContext() {
            return {
                selectedNoteId: null,
                selectedProjectId: null,
                selectedApClassId: null,
                selectedAssignmentId: null,
                selectedReviewDeckId: null,
                selectedReviewItemId: null,
                selectedCalendarDate: null,
                selectedFocusPreset: null,
                scrollPosition: 0,
                filters: {}
            };
        }

        function normalizePaneContext(raw) {
            const defaults = getDefaultPaneContext();
            if (!raw || typeof raw !== 'object') return defaults;
            const filters = raw.filters && typeof raw.filters === 'object' ? raw.filters : {};
            return {
                selectedNoteId: raw.selectedNoteId ? String(raw.selectedNoteId) : null,
                selectedProjectId: raw.selectedProjectId ? String(raw.selectedProjectId) : null,
                selectedApClassId: raw.selectedApClassId ? String(raw.selectedApClassId) : null,
                selectedAssignmentId: raw.selectedAssignmentId ? String(raw.selectedAssignmentId) : null,
                selectedReviewDeckId: raw.selectedReviewDeckId ? String(raw.selectedReviewDeckId) : null,
                selectedReviewItemId: raw.selectedReviewItemId ? String(raw.selectedReviewItemId) : null,
                selectedCalendarDate: raw.selectedCalendarDate ? String(raw.selectedCalendarDate) : null,
                selectedFocusPreset: raw.selectedFocusPreset ? String(raw.selectedFocusPreset) : null,
                scrollPosition: parseFloat(raw.scrollPosition) || 0,
                filters
            };
        }

        function normalizeSplitPaneContexts(raw) {
            const defaults = getDefaultSplitPaneContexts();
            if (!raw || typeof raw !== 'object') return defaults;
            const allowedViews = new Set([...OPTIONAL_FEATURE_VIEWS, 'settings']);
            const leftView = allowedViews.has(raw.leftView) ? raw.leftView : defaults.leftView;
            const rightView = allowedViews.has(raw.rightView) ? raw.rightView : defaults.rightView;
            const layout = ['half', 'left-wide', 'right-wide', 'thirds'].includes(raw.layout) ? raw.layout : 'half';
            return {
                leftView,
                rightView,
                layout,
                leftContext: normalizePaneContext(raw.leftContext),
                rightContext: normalizePaneContext(raw.rightContext),
                lastUpdatedAt: raw.lastUpdatedAt || null
            };
        }

        function normalizeRecentSearches(raw) {
            if (!Array.isArray(raw)) return [];
            return raw
                .map(entry => entry && typeof entry === 'object' ? { query: String(entry.query || '').slice(0, 200), at: entry.at || new Date().toISOString() } : null)
                .filter(Boolean)
                .slice(0, 25);
        }

        const PINNED_PAGE_TABS = ['life', 'collegeapp'];
        const VALID_LIFE_PAGE_IDS = new Set([
            'goals', 'habits', 'sleep', 'spending', 'journal',
            'skills', 'fitness', 'calories', 'calculator', 'books',
            'wellness'
        ]);
        const VALID_COLLEGEAPP_PAGE_IDS = new Set([
            'tracker', 'essays', 'scores', 'awards',
            'scholarships', 'decision', 'majordecision', 'sheets'
        ]);

        function getValidPinnedPageIds(tab) {
            if (tab === 'life') return VALID_LIFE_PAGE_IDS;
            if (tab === 'collegeapp') return VALID_COLLEGEAPP_PAGE_IDS;
            return new Set();
        }

        function getDefaultPinnedPages() {
            return { life: [], collegeapp: [], notesBySpace: {} };
        }

        function normalizePinnedIdList(rawList, validIds = null) {
            const seen = new Set();
            return (Array.isArray(rawList) ? rawList : [])
                .map(id => String(id || '').trim())
                .filter(id => {
                    if (!id || seen.has(id)) return false;
                    if (validIds && !validIds.has(id)) return false;
                    seen.add(id);
                    return true;
                });
        }

        function normalizePinnedPages(source) {
            const defaults = getDefaultPinnedPages();
            const data = source && typeof source === 'object' ? source : {};
            const out = {};
            PINNED_PAGE_TABS.forEach(tab => {
                const validIds = getValidPinnedPageIds(tab);
                const list = Array.isArray(data[tab]) ? data[tab] : defaults[tab];
                out[tab] = normalizePinnedIdList(list, validIds);
            });
            out.notesBySpace = {};
            const bySpace = data.notesBySpace && typeof data.notesBySpace === 'object' ? data.notesBySpace : {};
            Object.entries(bySpace).forEach(([spaceId, list]) => {
                const key = String(spaceId || '').trim();
                if (!key) return;
                const normalized = normalizePinnedIdList(list);
                if (normalized.length) out.notesBySpace[key] = normalized;
            });
            if (Array.isArray(data.notes)) {
                const legacyDefaultPins = normalizePinnedIdList(data.notes);
                if (legacyDefaultPins.length) out.notesBySpace.default = legacyDefaultPins;
            }
            return out;
        }

        function getPinnedPagesState() {
            if (!appData) return getDefaultPinnedPages();
            if (!appData.pinnedPages || typeof appData.pinnedPages !== 'object') {
                appData.pinnedPages = getDefaultPinnedPages();
            }
            PINNED_PAGE_TABS.forEach(tab => {
                if (!Array.isArray(appData.pinnedPages[tab])) appData.pinnedPages[tab] = [];
            });
            if (!appData.pinnedPages.notesBySpace || typeof appData.pinnedPages.notesBySpace !== 'object') {
                appData.pinnedPages.notesBySpace = {};
            }
            return appData.pinnedPages;
        }

        function isPagePinned(tabName, pageId) {
            if (!PINNED_PAGE_TABS.includes(tabName)) return false;
            const list = getPinnedPagesState()[tabName];
            return Array.isArray(list) && list.includes(String(pageId));
        }

        function getPinnedPages(tabName) {
            if (!PINNED_PAGE_TABS.includes(tabName)) return [];
            return getPinnedPagesState()[tabName].slice();
        }

        function getUnpinnedPages(tabName, allPageIds) {
            const pinned = new Set(getPinnedPages(tabName));
            return (Array.isArray(allPageIds) ? allPageIds : [])
                .map(id => String(id))
                .filter(id => !pinned.has(id));
        }

        function togglePinnedPage(tabName, pageId) {
            if (!PINNED_PAGE_TABS.includes(tabName)) return false;
            const id = String(pageId || '').trim();
            const validIds = getValidPinnedPageIds(tabName);
            if (!id || !validIds.has(id)) return false;
            const list = getPinnedPagesState()[tabName];
            const idx = list.indexOf(id);
            if (idx === -1) {
                list.push(id);
            } else {
                list.splice(idx, 1);
            }
            try { persistAppData(); } catch (err) { /* non-critical */ }
            return idx === -1;
        }

        function getPinnedNoteIdsForSpace(spaceId = activeSpaceId || 'default') {
            const key = String(spaceId || 'default').trim() || 'default';
            const state = getPinnedPagesState();
            const list = state.notesBySpace && Array.isArray(state.notesBySpace[key]) ? state.notesBySpace[key] : [];
            const validPageIds = new Set(
                (Array.isArray(pages) ? pages : [])
                    .filter(page => page && (page.spaceId || 'default') === key)
                    .map(page => String(page.id))
            );
            return normalizePinnedIdList(list).filter(id => validPageIds.has(id));
        }

        function isNotePagePinned(pageId, spaceId = activeSpaceId || 'default') {
            const id = String(pageId || '').trim();
            if (!id) return false;
            return getPinnedNoteIdsForSpace(spaceId).includes(id);
        }

        function cleanupPinnedNotePageRefs() {
            const state = getPinnedPagesState();
            const validBySpace = new Map();
            (Array.isArray(pages) ? pages : []).forEach(page => {
                if (!page || !page.id) return;
                const spaceId = String(page.spaceId || 'default');
                if (!validBySpace.has(spaceId)) validBySpace.set(spaceId, new Set());
                validBySpace.get(spaceId).add(String(page.id));
            });
            Object.keys(state.notesBySpace || {}).forEach(spaceId => {
                const valid = validBySpace.get(spaceId) || new Set();
                state.notesBySpace[spaceId] = normalizePinnedIdList(state.notesBySpace[spaceId]).filter(id => valid.has(id));
                if (!state.notesBySpace[spaceId].length) delete state.notesBySpace[spaceId];
            });
        }

        function toggleNotePagePin(pageId, spaceId = activeSpaceId || 'default') {
            const page = pages.find(entry => entry && entry.id === pageId);
            if (!page) return false;
            const key = String(spaceId || page.spaceId || 'default').trim() || 'default';
            if ((page.spaceId || 'default') !== key) return false;
            const state = getPinnedPagesState();
            if (!state.notesBySpace[key]) state.notesBySpace[key] = [];
            const list = state.notesBySpace[key];
            const id = String(pageId);
            const idx = list.indexOf(id);
            const pinned = idx === -1;
            if (pinned) list.push(id);
            else list.splice(idx, 1);
            cleanupPinnedNotePageRefs();
            try { persistAppData(); } catch (err) { /* non-critical */ }
            try { renderPagesList(); } catch (err) { /* non-critical */ }
            showToast(pinned ? 'Page pinned' : 'Page unpinned');
            return pinned;
        }

        // ---- Academic-planning workspaces (Semester Setup, Grade Planner,
        // School Schedule). The modules in src/features own the canonical
        // defaults + normalizers; these safe wrappers keep the core working
        // (and imports lossless) even if a module fails to load.
        function getDefaultSchoolScheduleSafe() {
            if (typeof window !== 'undefined' && typeof window.getDefaultSchoolSchedule === 'function') return window.getDefaultSchoolSchedule();
            return { schemaVersion: 1, enabled: false, term: {}, rotation: {}, schedules: [], defaultScheduleId: '', dayTemplates: {}, overrides: [], subscriptions: [], settings: {} };
        }
        function normalizeSchoolScheduleSafe(raw) {
            if (typeof window !== 'undefined' && typeof window.normalizeSchoolSchedule === 'function') return window.normalizeSchoolSchedule(raw);
            return (raw && typeof raw === 'object') ? raw : getDefaultSchoolScheduleSafe();
        }
        function getDefaultGradePlannerSafe() {
            if (typeof window !== 'undefined' && typeof window.getDefaultGradePlanner === 'function') return window.getDefaultGradePlanner();
            return { schemaVersion: 1, courses: {}, settings: {} };
        }
        function normalizeGradePlannerSafe(raw) {
            if (typeof window !== 'undefined' && typeof window.normalizeGradePlanner === 'function') return window.normalizeGradePlanner(raw);
            return (raw && typeof raw === 'object') ? raw : getDefaultGradePlannerSafe();
        }
        function getDefaultSemesterSetupSafe() {
            if (typeof window !== 'undefined' && typeof window.getDefaultSemesterSetup === 'function') return window.getDefaultSemesterSetup();
            return { schemaVersion: 1, drafts: [], lastCompletedAt: null };
        }
        function normalizeSemesterSetupSafe(raw) {
            if (typeof window !== 'undefined' && typeof window.normalizeSemesterSetup === 'function') return window.normalizeSemesterSetup(raw);
            return (raw && typeof raw === 'object') ? raw : getDefaultSemesterSetupSafe();
        }

        function normalizePdfDocumentsSafe(raw) {
            const engine = typeof window !== 'undefined' ? window.SutraPdfEngine : null;
            return (Array.isArray(raw) ? raw : []).map(item => engine && typeof engine.normalizeDocument === 'function'
                ? engine.normalizeDocument(item) : item).filter(Boolean);
        }

        function normalizePdfAnnotationsSafe(raw) {
            const engine = typeof window !== 'undefined' ? window.SutraPdfEngine : null;
            return (Array.isArray(raw) ? raw : []).map(item => engine && typeof engine.normalizeAnnotation === 'function'
                ? engine.normalizeAnnotation(item) : item).filter(Boolean);
        }

        function normalizeAttachmentLinksSafe(raw) {
            const engine = typeof window !== 'undefined' ? window.SutraPdfEngine : null;
            if (engine && typeof engine.normalizeAttachmentLinks === 'function') return engine.normalizeAttachmentLinks(raw);
            return Array.isArray(raw) ? raw.filter(Boolean) : [];
        }

